```bash
cd /home/vscode/nullness-benchmarks/litiengine && python - << 'EOF'
from pathlib import Path

path = Path("src/de/gurkenlabs/litiengine/graphics/Camera.java")
text = path.read_text()

old = """  @Override
  public void setFocus(@Nullable final Point2D focus) {
    this.focus = this.clampToMap(focus);

    // dunno why but without the factor of 0.01 sometimes everything starts to
"""
new = """  @Override
  public void setFocus(@Nullable final Point2D focus) {
    if (focus == null) {
      return;
